use bbt_supervisor::{Config, Supervisor};
use std::{ffi::CStr, io, path::{Path, PathBuf}, process::Command};

fn config(path: &Path) -> Config {
    Config { socket_path: Some(path.into()), ..Default::default() }
}
fn path_for_fd(fd: i32) -> Option<PathBuf> {
    let mut buffer = [0u8; 1024];
    let result = unsafe { libc::fcntl(fd, libc::F_GETPATH, buffer.as_mut_ptr()) };
    (result == 0).then(|| PathBuf::from(unsafe { CStr::from_ptr(buffer.as_ptr().cast()) }.to_string_lossy().into_owned()))
}
fn lock_fd(path: &Path) -> i32 {
    let expected = path.canonicalize().unwrap();
    (0..4096).find(|&fd| path_for_fd(fd).as_deref() == Some(expected.as_path())).expect("supervisor ownership fd")
}
fn pipe() -> [i32; 2] {
    let mut fds = [-1; 2];
    assert_eq!(unsafe { libc::pipe(fds.as_mut_ptr()) }, 0);
    fds
}
struct Child { pid: i32, release: i32 }
impl Drop for Child {
    fn drop(&mut self) {
        let byte = [1u8];
        unsafe { libc::write(self.release, byte.as_ptr().cast(), 1); libc::close(self.release); }
        let mut status = 0;
        loop {
            let result = unsafe { libc::waitpid(self.pid, &mut status, 0) };
            if result == self.pid { break; }
            assert_eq!(io::Error::last_os_error().kind(), io::ErrorKind::Interrupted);
        }
        println!("child_reaped pid={} wait_status={status}", self.pid);
        assert_eq!(status, 0);
    }
}
fn main() {
    let root = PathBuf::from(std::env::args_os().nth(1).expect("private probe directory"));
    std::fs::create_dir_all(&root).unwrap();
    let socket = root.join("run/mux.sock");
    let lock = root.join("run/mux.sock.lock");
    println!("probe_pid={} socket={}", std::process::id(), socket.display());
    for iteration in 1..=10 {
        let server = Supervisor::start(config(&socket)).unwrap();
        let fd = lock_fd(&lock);
        let flags = unsafe { libc::fcntl(fd, libc::F_GETFD) };
        assert_ne!(flags & libc::FD_CLOEXEC, 0);
        server.shutdown().unwrap();
        let parent_released = path_for_fd(fd).as_deref() != Some(lock.canonicalize().unwrap().as_path());
        assert!(parent_released);
        Supervisor::start(config(&socket)).unwrap().shutdown().unwrap();
        println!("no_fork iteration={iteration} original_fd={fd} cloexec=true parent_released=true immediate_restart=ok");
    }
    let server = Supervisor::start(config(&socket)).unwrap();
    let fd = lock_fd(&lock);
    let release = pipe(); let ready = pipe();
    let pid = unsafe { libc::fork() };
    assert!(pid >= 0);
    if pid == 0 {
        // After a multi-threaded fork, use only these libc operations until _exit.
        unsafe {
            libc::close(release[1]); libc::close(ready[0]);
            let flags = libc::fcntl(fd, libc::F_GETFD);
            let state = [u8::from(flags >= 0 && flags & libc::FD_CLOEXEC != 0)];
            libc::write(ready[1], state.as_ptr().cast(), 1); libc::close(ready[1]);
            let mut poll = libc::pollfd { fd: release[0], events: libc::POLLIN, revents: 0 };
            let waited = libc::poll(&mut poll, 1, 20_000);
            let mut byte = [0u8];
            let read = if waited > 0 { libc::read(release[0], byte.as_mut_ptr().cast(), 1) } else { -1 };
            libc::_exit(if read == 1 { 0 } else { 124 });
        }
    }
    unsafe { libc::close(release[0]); libc::close(ready[1]); }
    let child = Child { pid, release: release[1] };
    let mut poll = libc::pollfd { fd: ready[0], events: libc::POLLIN, revents: 0 };
    assert_eq!(unsafe { libc::poll(&mut poll, 1, 20_000) }, 1);
    let mut state = [0u8];
    assert_eq!(unsafe { libc::read(ready[0], state.as_mut_ptr().cast(), 1) }, 1);
    unsafe { libc::close(ready[0]); }
    assert_eq!(state, [1]);
    let live = Supervisor::start(config(&socket)).err().expect("live owner must refuse");
    assert_eq!(live.kind(), io::ErrorKind::AddrInUse);
    println!("fork_child_ready pid={pid} inherited_fd={fd} cloexec=true live_owner_refused={live}");
    server.shutdown().unwrap();
    let after = unsafe { libc::fcntl(fd, libc::F_GETFD) };
    let parent_error = io::Error::last_os_error();
    println!("after_shutdown original_parent_fd={fd} f_getfd={after} errno={parent_error}");
    assert_eq!(after, -1);
    assert_eq!(parent_error.raw_os_error(), Some(libc::EBADF));
    let blocked = Supervisor::start(config(&socket)).err().expect("inherited lock must still block");
    println!("after_shutdown fork_child_alive={pid} restart_kind={:?} restart_error={blocked}", blocked.kind());
    assert_eq!(blocked.kind(), io::ErrorKind::AddrInUse);
    assert!(blocked.to_string().contains("ownership lock"));
    let lsof = Command::new("/usr/sbin/lsof").args(["-nP", "-a", "-p", &pid.to_string(), "--"]).arg(&lock).output().unwrap();
    println!("lsof_exit={}\n{}", lsof.status, String::from_utf8_lossy(&lsof.stdout));
    assert!(lsof.status.success());
    drop(child);
    Supervisor::start(config(&socket)).unwrap().shutdown().unwrap();
    println!("after_child_reaped immediate_restart=ok");
}

